import{_ as a,o as t,c as i,aw as e}from"./chunks/framework.DLufY-ao.js";const g=JSON.parse('{"title":"Waterfall","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/dev-commit/theory/agile/models/waterfall.md","filePath":"wiki/dev-commit/theory/agile/models/waterfall.md"}'),r={name:"wiki/dev-commit/theory/agile/models/waterfall.md"};function o(s,l,n,d,c,h){return t(),i("div",null,[...l[0]||(l[0]=[e('<h1 id="waterfall" tabindex="-1">Waterfall <a class="header-anchor" href="#waterfall" aria-label="Permalink to &quot;Waterfall&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">Waterfall</p><ul><li><strong>Waterfall Model (каскадная модель)</strong> - модель процесса разработки программного обеспечения, в которой процесс разработки выглядит как поток, последовательно проходящий фазы.</li><li>Весь процесс является жестким и линейным, имеет четкие цели для каждого этапа, новая фаза начинается по завершению предыдущей, нет возврата назад</li></ul></div><h2 id="шаги" tabindex="-1">Шаги <a class="header-anchor" href="#шаги" aria-label="Permalink to &quot;Шаги&quot;">​</a></h2><ol><li><strong>Требования</strong> - список требований к ПО. В первую очередь, анализируются требования и пожелания заказчика, затем это проецируется на возможности компании и состояние рынка. В результате получается некий документ, где описывается, что должно делать ПО, но не как и с помощью каких инструментов</li><li><strong>Проектирование</strong> - согласовывается логика работы ПО. Здесь всё ещё не принимаются конкретные решения по реализации, но уже описывается функционирование всех разделов приложения. На выходе разработчики уже представляют, сколько по времени и кадровому составу может занять проект. Создаются документы, подробно описывающие для программистов способ и план реализации указанных требований</li><li><strong>Конструирование</strong> (также «реализация» либо «кодирование») - речь идёт о конкретных инструментах для реализации идей: согласовываются требования к дизайну, языки программирования, уровни данных, сервисы и т. д. Формируется внешний облик готового продукта</li><li><strong>Воплощение</strong> - исполнительский этап, на который, как правило, приходится большая часть разработки. Если классическая модель допускает свободное взаимодействие с предыдущими этапами, то на практике допускается лишь внесение незначительных правок в «Конструирование»</li><li><strong>Тестирование и отладка</strong> (также «верификация»)</li><li><strong>Инсталляция</strong></li><li><strong>Поддержка</strong></li></ol><h2 id="преимущества-и-недостатки" tabindex="-1">Преимущества и недостатки <a class="header-anchor" href="#преимущества-и-недостатки" aria-label="Permalink to &quot;Преимущества и недостатки&quot;">​</a></h2><p><strong>Преимущества</strong></p><ul><li>Устойчива к изменению кадрового состава Благодаря подробному документированию смена работников практически не влияет на сроки исполнения проекта</li><li>Дисциплина Модель заставляет разработчиков, вовлечённых в проект быть дисциплинированными, оставаться в рамках намеченного плана. При необходимости в общей модели добавляется орган управления, ответственный за принятие решений, исполнители же обязаны работать в рамках системы</li><li>Гибкость на ранних этапах Изменения в первых трёх фазах могут быть сделаны немедленно и с минимальными усилиями, поскольку они не подкреплены кодом</li><li>Ориентация на сроки и финансы Благодаря тому, что каждый этап полностью очерчивает контур будущего ПО, все разработчики понимают свою роль, границы работы и сроки исполнения. Это позволяет оперировать реальными цифрами перед заказчиком</li></ul><p><strong>Недостатки</strong></p><ul><li>Неадаптивная структура ПО На первых этапах модель водопада может быть гибкой, но если на фазе тестирования выявляются проблемы в общей структуре – это влечёт за собой последствия в виде сорванных сроков и даже отказов заказчика. Таким образом, возрастает роль руководителей и ответственных разработчиков, с уровнем компетентности которых в любой компании часто бывают проблемы</li><li>Игнорирует конечного пользователя Чем ниже продвигается процесс в водопаде, тем меньше в нём роль заказчика. Внесение каких-либо изменений в функциональность ПО запускает всю цепочку этапов заново, поэтому продукты полученные по каскадной модели далеки от ориентации на массового пользователя</li><li>Позднее тестирование Более гибкие методологии используют тестирование в качестве фундаментальной операции, происходящей непрерывно. Waterfall же допускает низкую квалификацию сотрудников на каждом этапе и плохое качество исполнения, ведь при запоздалом тестировании проблемы невозможно решить фундаментально</li></ul><h2 id="итого" tabindex="-1">Итого <a class="header-anchor" href="#итого" aria-label="Permalink to &quot;Итого&quot;">​</a></h2><ol><li>При ориентации ПО на заказчика, требующего прозрачность работ и исполнение в назначенные сроки</li><li>При наличии в штате руководителей соответствующей квалификации</li><li>При исполнении проекта, не имеющего конкуренции на рынке</li></ol>',11)])])}const m=a(r,[["render",o]]);export{g as __pageData,m as default};
